package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StdDateFormat._format method.
 * Since _format is protected, we use a subclass or access it via the public format method 
 * if possible, but since we need to test the specific protected logic, 
 * we create a Testable subclass.
 */
public class StdDateFormat__format_TriageGen2Test {

    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        public TestableStdDateFormat(boolean formatTzOffsetWithColon) {
            // Using the protected constructor to control _tzSerializedWithColon
            super(TimeZone.getDefault(), Locale.getDefault(), true, formatTzOffsetWithColon);
        }

        // Expose protected method for testing
        public void callFormat(TimeZone tz, Locale loc, Date date, StringBuffer buffer) {
            super._format(tz, loc, date, buffer);
        }
    }

    @Test
    public void testFormatWithUTCAndNoColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        TimeZone utc = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        // 2023-10-05 14:30:05.123
        Calendar cal = Calendar.getInstance(utc);
        cal.set(2023, Calendar.OCTOBER, 5, 14, 30, 5);
        cal.set(Calendar.MILLISECOND, 123);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df.callFormat(utc, loc, date, buffer);

        // Expected: 2023-10-05T14:30:05.123+0000
        assertEquals("2023-10-05T14:30:05.123+0000", buffer.toString());
    }

    @Test
    public void testFormatWithUTCAndColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(true);
        TimeZone utc = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(utc);
        cal.set(2023, Calendar.OCTOBER, 5, 14, 30, 5);
        cal.set(Calendar.MILLISECOND, 123);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df.callFormat(utc, loc, date, buffer);

        // Expected: 2023-10-05T14:30:05.123+00:00
        assertEquals("2023-10-05T14:30:05.123+00:00", buffer.toString());
    }

    @Test
    public void testFormatWithPositiveOffsetAndColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(true);
        // GMT+05:30 (India)
        TimeZone tz = TimeZone.getTimeZone("GMT+05:30");
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(tz);
        cal.set(2023, Calendar.DECEMBER, 25, 10, 0, 0);
        cal.set(Calendar.MILLISECOND, 5);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df.callFormat(tz, loc, date, buffer);

        // Offset is +05:30
        assertEquals("2023-12-25T10:00:00.005+05:30", buffer.toString());
    }

    @Test
    public void testFormatWithNegativeOffsetAndNoColon() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        // GMT-08:00 (PST)
        TimeZone tz = TimeZone.getTimeZone("GMT-08:00");
        Locale loc = Locale.US;

        Calendar cal = Calendar.getInstance(tz);
        cal.set(2023, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df.callFormat(tz, loc, date, buffer);

        // Offset is -08:00
        assertEquals("2023-01-01T00:00:00.000-08:00", buffer.toString());
    }

    @Test
    public void testFormatExtremeYear() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        TimeZone tz = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        // Test year 10000 (beyond 4 digits)
        Calendar cal = Calendar.getInstance(tz);
        cal.set(10000, Calendar.JANUARY, 1, 12, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df.callFormat(tz, loc, date, buffer);

        // The code uses pad4 which might pad or just append. 
        // Based on logic: pad4(buffer, 10000) -> "10000"
        assertEquals("10000-01-01T12:00:00.000+0000", buffer.toString());
    }

    @Test
    public void testFormatBCEYear() {
        TestableStdDateFormat df = new TestableStdDateFormat(false);
        TimeZone tz = TimeZone.getTimeZone("UTC");
        Locale loc = Locale.US;

        // Year -1 (1 BC)
        Calendar cal = Calendar.getInstance(tz);
        cal.set(-1, Calendar.JANUARY, 1, 12, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);
        Date date = cal.getTime();

        StringBuffer buffer = new StringBuffer();
        df.callFormat(tz, loc, date, buffer);

        // pad4 for negative numbers usually results in "-0001" or similar depending on implementation
        // but we test the logic flow.
        String result = buffer.toString();
        // Since we don't have the source of pad4, we assume it handles the sign.
        // Usually, in Jackson's StdDateFormat, it results in "-0001-01-01T12:00:00.000+0000"
        // We check if it contains the year.
        assert(result.contains("-01-01T12:00:00.000+0000"));
    }
}
